  "title": "Bill C-36 (45-1) Protecting Privacy and Consumer Data Act, LEGISinfo",
  "date": "first reading 15 Jun 2026",
  "text": "Federal privacy reform bill introduced 15 Jun 2026; at access still at second reading (no committee, Senate or assent)."
 },
 {
  "id": "R-038",
  "title": "APP 1.7-1.9 Transparency Obligation Fact Sheet (OAIC)",
  "date": "Sep 2026",
  "text": "Fact sheet confirms obligations commence 10 Dec 2026 and gives recruitment-software examples (algorithmic job-ad targeting by age/gender; AI-generated candidate profiles from video interviews) as decisions that may significantly affect rights or interests."
 }
